with src as (
  select * from jsonb_array_elements($j$[{"id":"vela","name":"VELA","author":"새벽코더","handle":"@nightshift","created_at":"2026-03-14T00:00:00Z","orbit":{"a":7.5,"e":0.06839413993060589,"inc":0.021027884222567083,"node":2.5575927544384442,"peri":1.8576202322875588,"phase":6.268389732621661},"look":{"tex":"swirl","pal":1,"size":0.85,"ring":false,"tilt":0.10488867515232414,"spin":-0.1668086470104754,"seed":354261853},"posts":[{"date":"2026-09-28","title":"CSS 한 줄로 별을 만들던 밤","body":"box-shadow 하나에 좌표 삼백 개를 밀어 넣으면 밤하늘이 된다. 새벽 세 시, 렌더링이 끝나는 순간 모니터가 조금 더 어두워진 것처럼 느껴졌다.\n\n성능은 최악이다. 그런데 가끔은 최악의 방법이 가장 정직한 방법일 때가 있다. 눈으로 보고, 손으로 고치고, 다시 본다.\n\n오늘의 결론: 최적화는 내일의 나에게. 오늘의 나는 별을 하나 더 찍는다."},{"date":"2026-10-11","title":"requestAnimationFrame과 화해하기","body":"setInterval로 버티던 애니메이션을 전부 rAF로 옮겼다. 탭을 숨기면 멈추고, 돌아오면 다시 숨을 쉰다. 이게 원래 맞는 거였다.\n\ndelta time을 곱하는 습관 하나가 60Hz와 144Hz 모니터 사이의 싸움을 끝냈다. 프레임이 아니라 시간을 기준으로 움직일 것.\n\n작은 원칙 하나가 코드 전체의 표정을 바꾼다."}]},{"id":"nori","name":"NORI","author":"노리","handle":"@noriyang","created_at":"2026-01-02T00:00:00Z","orbit":{"a":10,"e":0.09501598440110684,"inc":0.024837616765871647,"node":1.3073955449922114,"peri":4.259789869437886,"phase":0.4655913551659253},"look":{"tex":"spots","pal":3,"size":0.75,"ring":false,"tilt":-0.08996036646422,"spin":0.4853256892645732,"seed":564421293},"posts":[{"date":"2026-10-03","title":"자취 7년차의 김밥 공식","body":"밥 1공기, 참기름 1스푼, 소금 두 꼬집. 이 비율만 지키면 김밥은 배신하지 않는다.\n\n단무지는 물기를 꼭 짜고, 시금치는 데친 뒤 간장 아주 조금. 계란은 두껍게 부쳐서 길게 썬다. 김의 거친 면이 안쪽으로 오게 말면 터지지 않는다.\n\n썰기 전 칼에 참기름을 한 번 바르면, 그날 김밥은 이미 성공이다."}]},{"id":"moth9","name":"MOTH-9","author":"모스","handle":"@moth","created_at":"2025-11-20T00:00:00Z","orbit":{"a":12.5,"e":0.023203466627746822,"inc":-0.01714287330163643,"node":1.9643715311133587,"peri":3.568617476864863,"phase":0.7493333135859784},"look":{"tex":"craters","pal":9,"size":1,"ring":false,"tilt":-0.3152810813393444,"spin":0.23352899732999505,"seed":721483948},"posts":[{"date":"2026-08-17","title":"필름 한 롤, 서른여섯 번의 망설임","body":"디지털로는 한 장면에 스무 번을 누르지만, 필름으로는 한 번을 누르기 위해 스무 번을 망설인다.\n\n현상소에서 돌아온 스캔본에는 초점이 나간 사진이 절반이다. 그런데 이상하게도 흔들린 사진들이 그날의 공기를 더 잘 기억한다.\n\n다음 롤은 흑백으로. 색을 덜어내면 빛이 더 잘 보일 것 같아서."},{"date":"2026-10-09","title":"을지로 골목, ISO 400","body":"해가 지기 직전의 을지로는 노출계가 헷갈려 한다. 간판 불빛과 남은 하늘빛이 섞이는 그 20분.\n\n조리개 f/2.8, 셔터 1/60. 손이 떨리지 않게 숨을 반쯤 내쉰 상태에서 누른다.\n\n결과는 다음 주에 알 수 있다. 기다림까지가 사진이다."}]},{"id":"tide","name":"TIDE","author":"조수웅덩이","handle":"@tidepool","created_at":"2026-05-30T00:00:00Z","orbit":{"a":15,"e":0.0715423865057528,"inc":-0.0014629273675382138,"node":6.229928965319182,"peri":3.013062695824002,"phase":4.737629060032461},"look":{"tex":"bands","pal":8,"size":1.15,"ring":false,"tilt":0.32457166495732964,"spin":0.19021321007749065,"seed":641491991},"posts":[{"date":"2026-09-12","title":"제주 중문, 첫 번째 테이크오프","body":"보드 위에 일어선 시간은 정확히 2초였다. 그 2초를 위해 패들링을 마흔 번쯤 했다.\n\n파도는 기다려 주지 않지만, 다시 온다. 놓친 파도에 미련을 두면 다음 파도도 놓친다는 걸 바다에서 배웠다.\n\n내일 아침 조수 간만표: 만조 06:42. 알람을 다섯 시 반에 맞춘다."}]},{"id":"lumen","name":"LUMEN","author":"루멘랩","handle":"@lumen.lab","created_at":"2025-12-08T00:00:00Z","orbit":{"a":17.5,"e":0.050631133671849966,"inc":0.033264495234470816,"node":1.7256024364393119,"peri":2.3741992666778406,"phase":2.2696645608448933},"look":{"tex":"ice","pal":5,"size":0.9,"ring":false,"tilt":0.13882088440004736,"spin":0.16768814764218404,"seed":708764476},"posts":[{"date":"2026-10-14","title":"고정폭 글꼴이 아름다운 이유","body":"모든 글자가 같은 폭을 가진다는 건, 모든 글자가 같은 무게의 발언권을 가진다는 뜻이다. i와 m이 같은 자리를 차지한다.\n\n그 제약 덕분에 텍스트는 격자가 되고, 격자는 그림이 된다. ASCII 아트는 타이포그래피가 이미지로 넘어가는 경계선이다.\n\n자간을 조절할 수 없는 글꼴에서 우리는 오히려 리듬을 배운다."},{"date":"2026-07-22","title":"한글 본문 행간 1.7의 비밀","body":"라틴 문자 기준의 1.5 행간은 한글에서 답답하다. 네모 꼴의 글자는 위아래로 숨 쉴 공간이 더 필요하다.\n\n본문 16px, 행간 1.7, 단락 사이 1em. 이 세 숫자가 장문 가독성의 대부분을 해결한다."}]},{"id":"kafka","name":"KAFKA","author":"열람실","handle":"@readingroom","created_at":"2025-10-01T00:00:00Z","orbit":{"a":20,"e":0.02452631900086999,"inc":-0.02782255274942145,"node":4.198954978483349,"peri":1.002028965591324,"phase":4.889360503547548},"look":{"tex":"storm","pal":7,"size":1.6,"ring":true,"tilt":-0.1020316030830145,"spin":-0.5033405258785933,"seed":24925861},"posts":[{"date":"2026-09-30","title":"「변신」을 서른 살에 다시 읽었다","body":"열여덟 살에는 벌레가 된 그레고르가 불쌍했다. 서른 살에는 그의 가족이 이해가 됐다. 그게 더 슬펐다.\n\n책은 그대로인데 읽는 사람이 변한다. 그러니 좋은 책은 한 번 읽는 것이 아니라 여러 번 만나는 것이다.\n\n다음 달 독서 모임 책: 이탈로 칼비노, 「보이지 않는 도시들」."}]},{"id":"pixell","name":"PIXELL","author":"8비트","handle":"@8bit","created_at":"2026-02-11T00:00:00Z","orbit":{"a":22.5,"e":0.08204330945387482,"inc":0.03278481774730608,"node":1.0286338658836391,"peri":0.7456089231130231,"phase":5.301496674101899},"look":{"tex":"lava","pal":6,"size":1.05,"ring":false,"tilt":0.4000990904867649,"spin":0.5521949415793642,"seed":149565206},"posts":[{"date":"2026-10-06","title":"개발 로그 #14 — 점프에 관성 넣기","body":"점프 버튼을 짧게 누르면 낮게, 길게 누르면 높게. 이 한 줄의 차이가 조작감을 완전히 바꾼다.\n\n코요테 타임 0.1초, 점프 버퍼 0.12초 추가. 플레이어는 이 숫자를 모르지만 손끝은 정확히 안다.\n\n다음 목표: 벽 미끄러짐. 그리고 버그 47개."},{"date":"2026-08-29","title":"16색 팔레트로 노을 그리기","body":"색을 고를 수 없을 때 디더링이 시작된다. 두 색을 체크무늬로 섞으면 눈이 세 번째 색을 만들어 낸다.\n\n제약은 언제나 스타일이 된다."}]},{"id":"quiet","name":"QUIET","author":"조용한방","handle":"@quietroom","created_at":"2025-09-09T00:00:00Z","orbit":{"a":29,"e":0.04881863299757243,"inc":0.018375974006485194,"node":3.7859513413955352,"peri":0.11593201970824676,"phase":4.952703628991547},"look":{"tex":"bands","pal":4,"size":1.45,"ring":true,"tilt":0.28473456606734543,"spin":-0.22235490629682317,"seed":470330545},"posts":[{"date":"2026-10-18","title":"비 오는 화요일을 위한 플레이리스트","body":"01. 피아노 한 대와 빗소리\n02. 가사가 없는 재즈 트리오\n03. 볼륨을 3까지만 올리는 앰비언트\n\n음악은 방의 온도를 바꾼다. 이 목록은 섭씨 19도 정도의 방을 위한 것이다.\n\n이어폰 말고 스피커로, 창문은 조금만 열어 두기."}]},{"id":"okra","name":"OKRA","author":"초록손","handle":"@greenthumb","created_at":"2026-04-04T00:00:00Z","orbit":{"a":31.5,"e":0.02538154549896717,"inc":0.00543559153797105,"node":2.2120763152061658,"peri":2.7237819861898718,"phase":4.289843726375946},"look":{"tex":"spots","pal":0,"size":0.8,"ring":true,"tilt":0.12753456733189525,"spin":0.27640077903633936,"seed":378739690},"posts":[{"date":"2026-09-21","title":"베란다 텃밭 시즌 결산","body":"방울토마토 214알, 바질 무한, 고추 11개, 상추는 달팽이가 먼저 먹었다.\n\n가장 큰 수확은 아침마다 흙을 만지는 10분이었다. 식물은 서두르지 않는다. 그걸 보고 있으면 나도 조금 느려진다.\n\n겨울 계획: 실내에서 새싹채소, 그리고 화분 정리."}]},{"id":"hallo","name":"HALLO","author":"할로스튜디오","handle":"@hallo.studio","created_at":"2026-06-18T00:00:00Z","orbit":{"a":34,"e":0.05178926251828671,"inc":-0.014161521752830596,"node":1.435460676630414,"peri":2.834658525282773,"phase":3.0755773283350885},"look":{"tex":"swirl","pal":2,"size":1.2,"ring":true,"tilt":0.2985107471700758,"spin":0.40433457694016395,"seed":732466587},"posts":[{"date":"2026-10-01","title":"첫 개인전 D-30","body":"작업 스물네 점 중 아직 아홉 점이 미완성이다. 매일 하나씩 끝내면 된다고 계산해 놓고, 매일 하나씩 새로 시작한다.\n\n전시 제목은 「궤도」. 서로 다른 속도로 도는 것들이 잠깐 같은 자리에 머무는 순간에 대한 그림들이다.\n\n오프닝: 11월 첫째 주 토요일. 오시면 행성 스티커를 드립니다."}]},{"id":"meridian","name":"MERIDIAN","author":"자오선","handle":"@runner","created_at":"2026-01-27T00:00:00Z","orbit":{"a":37,"e":0.09092489885166288,"inc":0.014432198037393392,"node":0.5014517811937527,"peri":4.073635445644642,"phase":2.175270751935293},"look":{"tex":"craters","pal":6,"size":0.95,"ring":false,"tilt":0.2824346464360133,"spin":0.5258918559411541,"seed":616881217},"posts":[{"date":"2026-10-12","title":"풀코스 6주 전, 32km 지속주","body":"28km 지점에서 다리가 아니라 마음이 먼저 멈추려 했다. 그때부터는 1km씩만 생각했다.\n\n페이스 5분 40초, 심박 152. 숫자는 정직하고, 몸은 생각보다 오래 버틴다.\n\n회복식: 바나나 두 개, 국밥 한 그릇. 그리고 아무것도 안 하기."}]},{"id":"archive7","name":"ARCHIVE-7","author":"오래된신호","handle":"@oldsignal","created_at":"2025-08-20T00:00:00Z","orbit":{"a":40,"e":0.0939250042103231,"inc":0.009611442417372018,"node":6.263556419523341,"peri":5.898113889123669,"phase":4.746855361053504},"look":{"tex":"ice","pal":9,"size":1.3,"ring":true,"tilt":-0.03998488043434918,"spin":0.4866293358849362,"seed":71189282},"posts":[{"date":"2026-09-05","title":"보이저 1호는 지금도 말을 걸고 있다","body":"1977년에 떠난 탐사선이 아직도 신호를 보낸다. 빛의 속도로 하루 가까이 걸려 도착하는 아주 작은 목소리.\n\n그 안에는 지구의 소리를 담은 금빛 레코드가 실려 있다. 누군가 언젠가 들어 주기를 바라며.\n\n어쩌면 블로그도 비슷하다. 누가 읽을지 모르는 채로, 우리는 계속 궤도 밖으로 신호를 보낸다."}]},{"id":"rust","name":"RUST","author":"페러스","handle":"@ferrous","created_at":"2026-03-03T00:00:00Z","orbit":{"a":43,"e":0.0519341116398573,"inc":-0.01721579811302945,"node":4.079895671482462,"peri":6.256617433343857,"phase":5.444289012284511},"look":{"tex":"lava","pal":0,"size":1.1,"ring":false,"tilt":0.17994227085728198,"spin":0.5316716355155222,"seed":46482336},"posts":[{"date":"2026-10-16","title":"빌림 검사기와 싸운 지 3주째","body":"컴파일러가 거절할 때마다 처음엔 화가 났다. 지금은 고맙다. 런타임에서 터질 버그를 미리 막아 준 거니까.\n\n소유권은 결국 \"누가 책임지는가\"에 대한 질문이다. 코드에서도, 삶에서도.\n\n오늘의 진척: 라이프타임 표기 없이 컴파일 성공. 작은 승리."}]}]$j$::jsonb) as s(v)
), ins as (
  insert into public.planets (id, owner_id, is_seed, name, author, handle, orbit, look, created_at)
  select v->>'id', null, true, v->>'name', v->>'author', v->>'handle', v->'orbit', v->'look', (v->>'created_at')::timestamptz
  from src
  on conflict (id) do nothing
  returning id
)
insert into public.posts (planet_id, date, title, body, created_at)
select s.v->>'id', (p->>'date')::date, p->>'title', p->>'body', (p->>'date')::timestamptz
from src s
join ins on ins.id = s.v->>'id'
cross join lateral jsonb_array_elements(s.v->'posts') as p;